# Rebuild and solve in one cell
from itertools import combinations, permutations
from pysat.formula import CNF
from pysat.card import CardEnc, EncType
from pysat.solvers import Solver

n = 27

def edge_var(i, j):
    if i > j:
        i, j = j, i
    return i * n + j + 1

cnf = CNF()

for v in range(n):
    neighbors = [edge_var(v, u) for u in range(n) if u != v]
    cnf.extend(CardEnc.atleast(lits=neighbors, bound=3, encoding=EncType.seqcounter).clauses)
    cnf.extend(CardEnc.atmost(lits=neighbors, bound=5, encoding=EncType.seqcounter).clauses)

for i, j, k in combinations(range(n), 3):
    cnf.append([-edge_var(i,j), -edge_var(i,k), -edge_var(j,k)])

for x, y in combinations(range(n), 2):
    others = [v for v in range(n) if v != x and v != y]
    for u, v in combinations(others, 2):
        cnf.append([-edge_var(x,u), -edge_var(x,v), -edge_var(y,u), -edge_var(y,v)])

for combo in combinations(range(n), 5):
    a = combo[0]
    others = combo[1:]
    for perm in permutations(others):
        p1, p2, p3, p4 = perm
        if p1 < p4:
            cnf.append([-edge_var(a,p1), -edge_var(p1,p2), -edge_var(p2,p3), 
                        -edge_var(p3,p4), -edge_var(p4,a)])

print(f"CNF: {len(cnf.clauses)} clauses, {cnf.nv} vars")
print("Solving...")

with Solver(name='glucose3', bootstrap_with=cnf) as solver:
    result = solver.solve()
    print(f"SAT result: {result}")
    if result:
        model = solver.get_model()
        model_set = set(model)
        edges = []
        for i in range(n):
            for j in range(i+1, n):
                if edge_var(i, j) in model_set:
                    edges.append((i, j))
        print(f"Edges ({len(edges)}):", edges)
